#!/usr/bin/env node
/**
 * Turn the owner's `gemstone-cards.json` into a typed catalogue module.
 *
 * RUN THIS, DO NOT EDIT THE OUTPUT. The generated file is derived from the JSON
 * beside it, exactly as `beauty-catalog.ts` is derived from the product sheet,
 * and for the same reason: the next version of the data arrives as a file, and
 * diffing somebody's hand-edits against it is how a catalogue quietly stops
 * matching the source it claims to come from.
 *
 *     node scripts/gen-gem-catalog.mjs
 *
 * THREE THINGS ARE DERIVED HERE, and they are derivations rather than data:
 *
 *   `kind` comes from the card NUMBER, because the sheet's own ordering carries
 *   it — 1–9 are the Navaratna, 10–25 the sixteen upratna substitutes, 26–30
 *   the wellness stones sold without a prescription. That ordering is stated in
 *   the data sheet; if a future file reorders the cards this rule must change
 *   with it rather than silently reclassifying a stone.
 *
 *   `substituteFor` links each upratna to the primary sharing its planet. Nine
 *   planets, one primary each, so the join is unambiguous.
 *
 *   `slug`/`image` are passed through unchanged — the photographs were
 *   extracted from the owner's stone-pages HTML to public/assets/gems and are
 *   keyed by the same id.
 */
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const HERE = dirname(fileURLToPath(import.meta.url));
const SRC = join(HERE, '..', 'src', 'astrology', 'gems');
const raw = JSON.parse(readFileSync(join(SRC, 'gemstone-cards.json'), 'utf8'));

const PRIMARY_MAX = 9;
const SUBSTITUTE_MAX = 25;
const kindOf = (n) => (n <= PRIMARY_MAX ? 'primary' : n <= SUBSTITUTE_MAX ? 'substitute' : 'wellness');

const cards = raw.cards.slice().sort((a, b) => a.number - b.number);
const primaryOf = new Map();
for (const c of cards) if (kindOf(c.number) === 'primary') primaryOf.set(c.planet, c.id);

const q = (s) => `'${String(s).replace(/\\/g, '\\\\').replace(/'/g, "\\'")}'`;
const arr = (xs) => `[${xs.map(q).join(', ')}]`;

const rows = cards.map((c) => {
  const kind = kindOf(c.number);
  const sub = kind === 'substitute' ? primaryOf.get(c.planet) ?? null : null;
  return `  {
    number: ${c.number}, id: ${q(c.id)}, sku: ${q(c.sku)}, name: ${q(c.displayName)},
    planet: ${q(c.planet)}, numerologyNumber: ${c.numerologyNumber}, kind: ${q(kind)},
    substituteFor: ${sub ? q(sub) : 'null'},
    traits: ${arr(c.traits)},
    description: ${q(c.description)},
    whyRecommended: ${q(c.whyRecommended)},
    whatYouFeel: ${q(c.wearing.whatYouFeel)},
    wearingNote: ${q(c.wearing.note)},
    image: ${q(c.image.src)}, imageAlt: ${q(c.image.alt)},
    perCaratMinInr: ${c.pricePerCarat.min}, perCaratMaxInr: ${c.pricePerCarat.max},
    theme: { background: ${q(c.theme.background)}, title: ${q(c.theme.title)}, body: ${q(c.theme.body)}, accent: ${q(c.theme.accent)} },
  },`;
});

const out = `import type { Gem } from './gem-types';

/**
 * The thirty stones, generated from the owner's card database.
 *
 * GENERATED BY scripts/gen-gem-catalog.mjs FROM gemstone-cards.json. Edit that
 * file and re-run; do not edit this one. The header of the generator lists the
 * three fields derived here rather than carried in the source.
 *
 * WHAT THIS IS NOT. It is a catalogue, not a prescription. Nothing in this file
 * decides which stone anybody should wear — the recommendation lives in
 * gem-recommend.ts and reads a chart to do it. Keeping the shelf and the
 * prescribing apart is what stops the marketplace from selling whatever is
 * nearest to hand.
 *
 * PRICES ARE INDICATIVE, per the data sheet: four retail tiers compiled from
 * Indian retailers in August 2026, to be replaced by a supplier feed before
 * launch. The spread between min and max IS the quality axis the citizen moves.
 */
export const GEMS: Gem[] = [
${rows.join('\n')}
];

/** By id, for the joins every other file needs. */
export const GEM_BY_ID = new Map(GEMS.map((g) => [g.id, g]));

/** The nine primaries, by planet. One each, by construction. */
export const PRIMARY_BY_PLANET = new Map(
  GEMS.filter((g) => g.kind === 'primary').map((g) => [g.planet, g]),
);
`;

writeFileSync(join(SRC, 'gem-catalog.ts'), out);
const counts = cards.reduce((m, c) => ({ ...m, [kindOf(c.number)]: (m[kindOf(c.number)] ?? 0) + 1 }), {});
console.log(`gem-catalog.ts — ${cards.length} stones`, counts);
